/bin/bash -lc "set -eu
tmp_dir=\"/Users/d111879/Documents/Project/DEMO/Student/Student_mobile/sapp/research/agent_runs/madhya-pradesh-government-verified-v2/workspaces/government-college-patharia/tmp/patharia-verify.aNF5gJ\"
for url in \\
  'https://damoh.nic.in/en/public-utility/govt-college-patharia/' \\
  'https://damoh.nic.in/public-utility/govt-college-patharia/' \\
  'http://damoh.nic.in/en/public-utility/govt-college-patharia/'; do
  out=\""'$tmp_dir/$(printf '"'%s' \""'$url" | sed '"'s#["'^A-Za-z0-9]#_#g'"').html\"; echo \"--- "'$url";
  curl -k -L --fail --max-time 30 -sS "$url" -o "$out"; echo "bytes $(wc -c < "$out")";
  rg -in -o '"'.{0,180}(Patharia|Website|website|mp\\.gov|college|Email|Phone|Address).{0,450}' \""'$out" | head -60 || true;
done'

